#!/usr/bin/env python3
from __future__ import annotations
import pathlib, sys
ROOT=pathlib.Path(__file__).resolve().parents[1]
def text(p): return (ROOT/p).read_text()
checks=[]
def check(n,c): checks.append((n,c))
cargo=text('Cargo.toml'); idx=text('crates/sparkbridge-index/src/lib.rs'); idx_cargo=text('crates/sparkbridge-index/Cargo.toml')
core=text('crates/sparkbridge-core/src/lib.rs'); protocol=text('crates/sparkbridge-protocol/src/lib.rs'); snap=text('crates/sparkbridge-snapshot/src/lib.rs')
config=text('crates/sparkbridge-config/src/lib.rs'); server=text('apps/sparkbridge-server/src/main.rs'); repo=text('apps/sparkbridge-server/src/repository.rs'); store=text('apps/sparkbridge-server/src/store.rs')
runtime=text('apps/sparkbridge-server/src/agent_runtime.rs'); task=text('crates/sparkbridge-task/src/lib.rs'); executor=text('apps/sparkbridge-executor/src/main.rs'); cli=text('apps/sparkbridge-cli/src/main.rs')
check('workspace version 0.12.0','version = "0.12.0"' in cargo)
check('protocol is 1.10','PROTOCOL_MINOR: u16 = 10' in protocol)
check('schema is v9','SCHEMA_VERSION: u32 = 9' in store and 'PRAGMA user_version = 9' in store)
check('repository index crate is workspace member','crates/sparkbridge-index' in cargo)
check('tree-sitter runtime is pinned for MSRV','tree-sitter = "0.25.10"' in idx_cargo and 'rust-version = "1.85"' in cargo)
check('major portable grammars are present',all(x in idx_cargo for x in ['tree-sitter-rust','tree-sitter-python','tree-sitter-c =','tree-sitter-cpp','tree-sitter-javascript','tree-sitter-typescript']))
check('index is snapshot keyed','pub snapshot_id: String' in idx and 'pub manifest_digest: String' in idx)
check('index stores files symbols references',all(x in idx for x in ['pub files: Vec<IndexedFile>','pub symbols: Vec<SymbolRecord>','pub references: Vec<ReferenceRecord>']))
check('index has explicit truncation evidence','pub truncated: bool' in idx)
check('index budgets exist',all(x in config for x in ['intelligence_max_file_bytes','intelligence_max_files','intelligence_max_symbols','intelligence_max_references']))
check('tree-sitter covers Rust/Python/C/C++/JS/TS',all(x in idx for x in ['tree_sitter_rust::LANGUAGE','tree_sitter_python::LANGUAGE','tree_sitter_c::LANGUAGE','tree_sitter_cpp::LANGUAGE','tree_sitter_javascript::LANGUAGE','LANGUAGE_TYPESCRIPT','LANGUAGE_TSX']))
check('Swift remains portable through structural fallback','SourceLanguage::Swift' in idx and 'parse_structural_fallback' in idx)
check('exact lexical search exists','pub fn lexical_search' in idx)
check('symbol search exists','pub fn symbol_search' in idx)
check('reference search exists','pub fn reference_search' in idx)
check('ranked path selection exists','pub fn rank_paths' in idx)
check('Git history is captured in snapshot','recent_commits' in snap and '["log","-n","32"' in snap)
check('Git history read path is exposed','pub fn git_history' in idx and '/history' in server)
check('repository indexes persist durably','CREATE TABLE IF NOT EXISTS repository_indexes' in store and 'register_repository_index' in store)
check('index body lives in CAS','state.cas.put_bytes(None,&encoded)' in repo and 'index_digest' in repo)
check('server lazily ensures index','pub fn ensure_index' in repo and 'record.manifest_digest == snapshot_record.manifest_digest' in repo)
check('admin intelligence routes exist',all(x in server for x in ['/api/v1/admin/indexes','/search','/symbols','/references','/history']))
check('CLI exposes intelligence lifecycle',all(x in cli for x in ['IntelligenceCommand::List','IntelligenceCommand::Build','IntelligenceCommand::Search','IntelligenceCommand::Symbols','IntelligenceCommand::References','IntelligenceCommand::History']))
check('context bundle can carry intelligence','pub intelligence: Option<serde_json::Value>' in task)
check('manual context remains highest priority','task.spec.context_paths.iter().chain(candidate_paths.iter()).chain(task.evidence_paths.iter()).chain(ranked_paths.iter())' in runtime)
check('candidate paths outrank discovered paths','candidate_paths.iter()).chain(task.evidence_paths.iter()).chain(ranked_paths.iter())' in runtime)
check('diagnostic files outrank discovered paths','task.evidence_paths.iter()).chain(ranked_paths.iter())' in runtime)
check('context compiler invokes repository intelligence','context_intelligence' in runtime and 'intelligence_query' in runtime)
check('context bundles version intelligence format','format_version: 2' in runtime and 'intelligence: Some(intelligence)' in runtime)
check('iteration 8 features negotiate','ITERATION_8_INTELLIGENCE' in core and all(x in core for x in ['RepositoryIntelligence','TreeSitterIndex','NativeLanguageAdapters']))
check('server negotiates intelligence features','ITERATION_8_INTELLIGENCE' in server)
check('native report is snapshot/workspace bound','report.snapshot_id!=snapshot_id' in repo and 'report.workspace_id!=snapshot_record.workspace_id' in repo)
check('native report paths must exist in immutable snapshot','native intelligence references a path outside the snapshot' in repo)
check('native reports persist through CAS','register_native_intelligence' in store and 'report_digest' in store and 'state.cas.put_bytes(None,&bytes)' in repo)
check('native LSP collection is bounded','intelligence_native_max_files' in config and 'intelligence_native_file_max_bytes' in config)
check('native LSP commands are configurable','intelligence_lsp_commands' in config and 'default_lsp_commands' in config)
check('native adapters include SourceKit rust-analyzer clangd Roslyn',all(x in idx for x in ['sourcekit-lsp','rust-analyzer','clangd','Microsoft.CodeAnalysis.LanguageServer']))
check('native collection uses stdio JSON-RPC','Content-Length:' in idx and 'textDocument/documentSymbol' in idx and 'textDocument/didOpen' in idx)
check('executor advertises native adapters','repository_intelligence_adapters' in executor)
check('executor supports explicit native intelligence upload','native_intelligence' in executor and 'collect_and_upload_native_intelligence' in executor)
check('native upload stays on mTLS fabric','/native-intelligence' in executor and 'fabric_url' in executor)
check('server exposes authenticated native upload route','/native-intelligence' in server and 'register_native_intelligence' in server)
check('native symbols can influence context ranking','native_symbol_matches' in repo and 'paths.insert(0,symbol.path.clone())' in repo)
check('language counts are context evidence','language_file_counts' in repo and 'extension_counts' in repo)
check('index stats are context evidence','index_stats' in repo and 'truncated' in repo)
check('agent still cannot auto-promote','promote_candidate' not in runtime)
check('executor native pass is optional','native_intelligence: bool' in executor)
failed=[n for n,c in checks if not c]
for n,c in checks: print(('PASS' if c else 'FAIL')+': '+n)
if failed:
    print(f'\n{len(failed)} repository intelligence invariant(s) failed',file=sys.stderr); sys.exit(1)
print(f'\nRepository Intelligence audit passed: {len(checks)} invariants')
